I18N_CATALOG = I18nCatalogDict(_RAW_CATALOG)


def get_translation(key, lang=None, default=None):
    if not key:
        return default if default is not None else key
    if not lang or lang == 'ar':
        return default if default is not None else key
    if key in I18N_CATALOG:
        entry = I18N_CATALOG[key]
        if hasattr(entry, 'for_lang'):
            return entry.for_lang(lang)
        if isinstance(entry, dict):
            return entry.get(lang, entry.get('en', default if default is not None else key))
        return entry
    return default if default is not None else key
